package local.pocketchat;

import java.util.*;

public final class LatencyProbePolicyTest {
  static int checks;
  static void check(String name,boolean value){if(!value)throw new AssertionError(name);checks++;}
  static Map<String,Object> warm(){Map<String,Object> m=new LinkedHashMap<>();m.put("schema",1);m.put("kind","warm");m.put("firstMs",410L);m.put("warmMs",105L);m.put("totalMs",517L);m.put("warmAttempted",true);m.put("warmSucceeded",true);m.put("secondConnectionReused",true);m.put("warmError","");m.put("firstStatus",204);m.put("secondStatus",204);return m;}
  static void bad(String name,String key,Object value){Map<String,Object> m=warm();m.put(key,value);check(name,LatencyProbePolicy.parse(m,105)==null);}
  public static void main(String[] args){
    LatencyProbePolicy.Trace t=LatencyProbePolicy.parse(warm(),105);check("An actual successful reused connection is comparable",t!=null&&t.comparable());check("Native first and total durations are retained, not subtracted from warm latency",t.first==410&&t.warm==105&&t.total==517);
    Map<String,Object> m=warm();m.put("kind","cold-retest");m.put("secondConnectionReused",false);t=LatencyProbePolicy.parse(m,105);check("Successful second request on a new connection is not a warm sample",t!=null&&!t.comparable());check("A cold retest keeps the actual measured number",LatencyProbePolicy.label(t.kind,105).equals("复测 105 ms"));
    m=warm();m.put("kind","cold-fallback");m.put("warmSucceeded",false);m.put("secondConnectionReused",false);m.put("warmMs",900L);m.put("totalMs",1312L);m.put("secondStatus",0);m.put("warmError","transport");t=LatencyProbePolicy.parse(m,410);check("A failed second request keeps the successful first request",t!=null&&t.first==410&&t.warm==900&&!t.comparable());check("Fallback is visibly first-request time rather than 1312 accumulated milliseconds",LatencyProbePolicy.label(t.kind,410).equals("首次 410 ms"));check("Accumulated fallback cannot masquerade as first delay",LatencyProbePolicy.parse(m,1312)==null);
    for(String error:Arrays.asList("cancelled","timeout","transport")){m.put("warmError",error);check("The fixed native error enum "+error+" is accepted",LatencyProbePolicy.parse(m,410)!=null);check("A friendly enum message does not expose an endpoint",!LatencyProbePolicy.error(error,0).contains("http"));}
    m.put("warmError","");m.put("secondStatus",403);check("A rejected HTTP response can be a failed retest without a transport error",LatencyProbePolicy.parse(m,410)!=null);check("HTTP mismatch uses a fixed friendly sentence",LatencyProbePolicy.error("",403).equals("复测响应未通过"));
    m=warm();m.put("kind","first");m.put("warmAttempted",false);m.put("warmSucceeded",false);m.put("secondConnectionReused",false);m.put("warmMs",-1L);m.put("secondStatus",0);m.put("totalMs",410L);t=LatencyProbePolicy.parse(m,410);check("A first-only native measurement is retained but excluded from ranking",t!=null&&!t.comparable());check("Unknown legacy latency is not presented as confirmed warm",LatencyProbePolicy.label("unknown",400).equals("400 ms"));
    for(String field:LatencyProbePolicy.REQUIRED_FIELDS){m=warm();m.remove(field);check("Missing field is conservatively unknown: "+field,LatencyProbePolicy.parse(m,105)==null);}
    bad("Future schema requires an explicit consumer update","schema",2);bad("String schema is not coerced","schema","1");bad("Decimal timing is not coerced","warmMs",105.0);bad("String timing is not coerced","warmMs","105");bad("Negative first time is rejected","firstMs",-1L);bad("Out-of-range total time is rejected","totalMs",120001L);bad("Total time cannot precede the first request","totalMs",409L);bad("Second request cannot exceed total time","warmMs",518L);bad("String boolean is not coerced","warmSucceeded","true");bad("Warm kind must have an actual successful second request","warmSucceeded",false);bad("Warm kind requires actual reuse evidence","secondConnectionReused",false);bad("Unknown kind is rejected","kind","estimated-warm");bad("Raw error cannot enter the public result","warmError","failed https://node.example/?password=secret");bad("A failed response is not a successful warm sample","secondStatus",403);bad("Malformed HTTP status is rejected","firstStatus",700);check("Reported delay and warm duration must agree exactly",LatencyProbePolicy.parse(warm(),104)==null);check("Unknown and missing traces stay unknown",LatencyProbePolicy.parse(null,400)==null);check("Failed top-level samples cannot gain an otherwise valid trace",LatencyProbePolicy.parse(warm(),-1)==null);
    m=warm();m.put("url","https://secret.example/");m.put("token","private");t=LatencyProbePolicy.parse(m,105);check("Only the fixed public fields are copied out",t!=null&&t.values().keySet().equals(LatencyProbePolicy.REQUIRED_FIELDS));check("No secret field survives the public trace",!t.values().toString().contains("secret")&&!t.values().toString().contains("private"));
    m=warm();m.put("firstStatus",403);check("A first HTTP rejection followed by a successful reused second response remains a valid native result",LatencyProbePolicy.parse(m,105)!=null);
    m=warm();m.put("dialCount",1);m.put("attempts",2);t=LatencyProbePolicy.parse(m,105);check("Actual native dial and request counters are retained",t!=null&&t.dials==1&&t.requests==2&&t.values().get("attempts").equals(2));
    for(String key:Arrays.asList("dialCount","attempts"))for(Object invalid:Arrays.asList(-1,129,"2",2.0)){m=warm();m.put(key,invalid);check("Optional counter is strictly bounded and typed: "+key+"="+invalid,LatencyProbePolicy.parse(m,105)==null);}
    check("Only a confirmed warm kind may enter comparable ranking",LatencyProbePolicy.comparable("warm",105)&&!LatencyProbePolicy.comparable("unknown",105)&&!LatencyProbePolicy.comparable("cold-retest",105)&&!LatencyProbePolicy.comparable("cold-fallback",105)&&!LatencyProbePolicy.comparable("first",105)&&!LatencyProbePolicy.comparable("warm",-1));
    check("Candidate cannot become current merely because its route and entry match",!LatencyProbePolicy.currentSample("candidate","route-A","route-A"));check("Old core or route receipts cannot become current",!LatencyProbePolicy.currentSample("current","route-A","route-B"));check("Only the exact current attribution is visible",LatencyProbePolicy.currentSample("current","route-A","route-A"));check("Legacy readings can remain visible without claiming a warm trace",LatencyProbePolicy.currentSample("","","route-A"));
    LatencyProbePolicy.Binding current=new LatencyProbePolicy.Binding("FixedExit","entry-A","epoch-A",3,40,7777),candidate=new LatencyProbePolicy.Binding("ProbeExit2","entry-B","epoch-A",3,41,7777);
    check("The current proxy requires its exact selected entry",current.matches("epoch-A",3,7777,"entry-A")&&!current.matches("epoch-A",3,7777,"entry-B"));check("Candidate is attributable to its own entry without pretending it is current",!candidate.current&&candidate.entry.equals("entry-B")&&candidate.matches("epoch-A",3,7777,"entry-A"));check("Identical delay values cannot substitute a candidate's unique measurement",current.measurement!=candidate.measurement);check("A changed core token invalidates both results",!current.matches("epoch-B",3,7777,"entry-A")&&!candidate.matches("epoch-B",3,7777,"entry-A"));check("Route A to B to A cannot revive a previous result",!current.matches("epoch-A",5,7777,"entry-A"));check("A changed controller cannot accept a prior response",!current.matches("epoch-A",3,8888,"entry-A"));check("Candidate results are also invalidated by route changes",!candidate.matches("epoch-A",4,7777,"entry-A"));
    m=warm();m.put("phaseSchema",1);m.put("chainMs",200L);m.put("tlsMs",100L);m.put("responseWaitMs",105L);m.put("dnsMs",-1L);
    t=LatencyProbePolicy.parse(m,105);check("First-request phases survive without changing warm latency",t!=null&&t.warm==105&&t.values().get("chainMs").equals(200L)&&t.values().get("dnsMs").equals(-1L));
    for(String field:LatencyProbePolicy.PHASE_FIELDS){Map<String,Object> missing=new LinkedHashMap<>(m);missing.remove(field);check("Incomplete phase object rejected: "+field,LatencyProbePolicy.parse(missing,105)==null);}
    for(String field:Arrays.asList("chainMs","tlsMs","responseWaitMs"))for(Object invalid:Arrays.asList(-2L,411L,"100",1.5)){Map<String,Object> invalidPhase=new LinkedHashMap<>(m);invalidPhase.put(field,invalid);check("Invalid phase rejected: "+field+invalid,LatencyProbePolicy.parse(invalidPhase,105)==null);}
    m.put("dnsMs",0L);check("Unavailable DNS cannot be presented as free",LatencyProbePolicy.parse(m,105)==null);
    System.out.println("{\"passed\":"+checks+",\"scope\":\"strict production native trace parsing, cold/warm classification, safe labels and exact route binding on JVM; no phone latency claim\"}");
  }
}
